public void AndroidThunkJava_OpenClubXEmail(String email)
{
    try
    {
        Intent intent = new Intent(Intent.ACTION_SENDTO);
        intent.setData(Uri.parse("mailto:" + email));

        Intent chooser = Intent.createChooser(intent, "Choose Email App");
        startActivity(chooser);
    }
    catch (Exception e)
    {
        e.printStackTrace();
    }
}
